insert into public.stories (id, kind, status, lang, source_url, source_name, attribution, published_at, content, tags, incomplete) values
  ('demo-parents-medicine', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"Родители хотели видеть меня врачом","kk":"Ата-анам мені дәрігер болғанымды қалады","en":"My parents wanted me to become a doctor"},"categories":["other-than-parents"],"ageRange":"18-24","before":{"ru":"Она росла в небольшом городе, где профессия врача считалась самой надёжной. Родители с детства говорили, что поступать нужно на лечебное дело.","kk":"Ол шағын қалада өсті, онда дәрігер мамандығы ең сенімді саналатын. Ата-анасы бала кезінен емдеу ісіне түсу керек деп айтып келді.","en":"She grew up in a small town where being a doctor was seen as the safest profession. Her parents had told her since childhood that she should apply for medicine."},"challenges":{"ru":"Анатомия давалась тяжело, а на пробных занятиях по биологии ей становилось тревожно. Было страшно разочаровать семью и потерять год.","kk":"Анатомия қиын болды, биологиядан сынақ сабақтарында ол алаңдайтын. Отбасын ренжітіп, бір жылын жоғалтудан қорықты.","en":"Anatomy was hard for her, and trial biology classes made her anxious. She was afraid of letting her family down and losing a year."},"turningPoint":{"ru":"Она записалась на бесплатные лекции по психологии и поняла, что её интересует не лечение, а то, как люди думают и принимают решения.","kk":"Ол психологиядан тегін дәрістерге жазылды және оны емдеу емес, адамдардың қалай ойлайтыны мен шешім қабылдайтыны қызықтыратынын түсінді.","en":"She signed up for free psychology lectures and realised she was interested not in treating illness but in how people think and make decisions."},"actions":{"ru":"Она поговорила с родителями и показала, чем занимаются психологи. Потом поступила на психологию и в первый год волонтёрила на телефоне доверия для школьников.","kk":"Ол ата-анасымен сөйлесіп, психологтардың немен айналысатынын көрсетті. Кейін психологияға түсіп, бірінші жылы мектеп оқушыларына арналған сенім телефонында ерікті болды.","en":"She talked to her parents and showed them what psychologists actually do. Then she enrolled in psychology and, in her first year, volunteered on a helpline for school students."},"now":{"ru":"Сейчас она на третьем курсе, родители постепенно привыкают к её выбору. Она всё ещё сомневается, какую именно специализацию выбрать.","kk":"Қазір ол үшінші курста, ата-анасы оның таңдауына біртіндеп үйреніп келеді. Қай мамандануды таңдау керектігіне ол әлі күмәнданады.","en":"She is now in her third year, and her parents are slowly getting used to her choice. She is still unsure which specialisation to pick."},"advice":{"ru":"Покажи близким конкретную профессию и путь к ней, а не только слова «это не моё».","kk":"Жақындарыңа «бұл маған сай емес» деп қана емес, нақты мамандық пен оған апаратын жолды көрсет.","en":"Show your family a concrete profession and the path to it, not just \"this isn''t for me\"."}}'::jsonb, '{"start":["small-town","family-pressure"],"interests":["people","health"],"fears":["disappointing-parents","wrong-choice"],"education":["school","university"],"challenges":["family","confidence"],"motives":["family","curiosity"],"decisions":["experiments","volunteering"],"transitions":["school-to-university"]}'::jsonb, '[]'::jsonb),
  ('demo-changed-major', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"Я перешёл с юриспруденции на дизайн","kk":"Мен заңгерліктен дизайнға ауыстым","en":"I switched from law to design"},"categories":["changed-major"],"ageRange":"18-24","before":{"ru":"Он поступил на юридический, потому что это престижно и «с этим всегда будет работа». Первый год он учился хорошо, но без интереса.","kk":"Ол заң факультетіне «бұл беделді және жұмыс әрдайым табылады» деп түсті. Бірінші жылы жақсы оқыды, бірақ қызығушылықсыз.","en":"He enrolled in law because it was prestigious and \"there is always work\". He did well in the first year but without real interest."},"challenges":{"ru":"На втором курсе пропала мотивация. Он боялся, что перевод означает потерянное время и деньги.","kk":"Екінші курста мотивация жоғалды. Ауысу уақыт пен ақшаны жоғалту дегенді білдіреді деп қорықты.","en":"In the second year his motivation faded. He was afraid a transfer would mean lost time and money."},"turningPoint":{"ru":"В свободное время он сделал сайт для друга и неожиданно просидел над ним всю ночь, не заметив времени.","kk":"Бос уақытында досына сайт жасап, уақыттың қалай өткенін байқамай, түні бойы отырып қалды.","en":"In his free time he built a website for a friend and, to his surprise, worked on it all night without noticing the time."},"actions":{"ru":"Две недели он собирал мини-портфолио, поговорил с деканом о переводе и прошёл онлайн-курс по основам дизайна. В итоге перевёлся, потеряв один семестр.","kk":"Ол екі апта шағын портфолио жинады, деканмен ауысу туралы сөйлесті және дизайн негіздері бойынша онлайн курс өтті. Нәтижесінде бір семестр жоғалтып, ауысты.","en":"For two weeks he put together a small portfolio, talked to the dean about a transfer and took an online course in design basics. He transferred, losing one semester."},"now":{"ru":"Сейчас он учится на дизайне и берёт небольшие заказы. Он считает, что семестр того стоил, но решение далось непросто.","kk":"Қазір ол дизайнда оқиды және шағын тапсырыстар алады. Бір семестр құнды болды деп санайды, бірақ шешім оңай болған жоқ.","en":"He now studies design and takes small freelance jobs. He says the semester was worth it, though the decision was not easy."},"advice":{"ru":"Проверь интерес маленьким проектом до того, как менять факультет.","kk":"Факультетті ауыстырудан бұрын қызығушылығыңды шағын жобамен тексер.","en":"Test your interest with a small project before you change faculty."}}'::jsonb, '{"start":["big-city"],"interests":["creative","tech"],"fears":["money","too-late"],"education":["university","changed-major"],"challenges":["confidence","time"],"motives":["curiosity","freedom"],"decisions":["switch-major","side-project"],"transitions":["major-change"]}'::jsonb, '[]'::jsonb),
  ('demo-volunteering-development', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"Волонтёрство привело меня к международному развитию","kk":"Еріктілік мені халықаралық дамуға алып келді","en":"Volunteering led me to international development"},"categories":["unexpected-passion"],"ageRange":"18-24","before":{"ru":"Она училась на экономике без чёткой цели и просто хотела получить диплом.","kk":"Ол экономикада нақты мақсатсыз оқыды және жай ғана диплом алғысы келді.","en":"She studied economics without a clear goal and mainly wanted to finish with a diploma."},"challenges":{"ru":"Она не знала, куда применить знания. Английский был на среднем уровне, а о работе в международных организациях она почти ничего не знала.","kk":"Ол білімін қайда қолдану керектігін білмеді. Ағылшын тілі орташа еді, ал халықаралық ұйымдардағы жұмыс туралы дерлік ештеңе білмеді.","en":"She did not know where to use her knowledge. Her English was average, and she knew almost nothing about working in international organisations."},"turningPoint":{"ru":"В студенческом клубе она помогала организовать благотворительную акцию и увидела, что её расчёты меняют то, как работает проект.","kk":"Студенттік клубта ол қайырымдылық акциясын ұйымдастыруға көмектесті және оның есептеулері жобаның жұмысын өзгертетінін көрді.","en":"In a student club she helped organise a charity event and saw that her calculations changed how the project worked."},"actions":{"ru":"Она стала регулярно волонтёрить, прошла бесплатные онлайн-курсы по управлению проектами, подтянула английский и сделала стажировку в местной некоммерческой организации.","kk":"Ол үнемі ерікті болды, жобаларды басқару бойынша тегін онлайн курстар өтті, ағылшын тілін жақсартты және жергілікті коммерциялық емес ұйымда тағылымдамадан өтті.","en":"She started volunteering regularly, took free online project-management courses, improved her English and did an internship at a local non-profit."},"now":{"ru":"Она готовит заявки в магистратуру по международному развитию, пока без гарантий результата.","kk":"Ол халықаралық даму бойынша магистратураға өтінімдер дайындап жүр, нәтиже әзірге кепілдендірілмеген.","en":"She is preparing applications for a master''s in international development, with no guarantee of the result yet."},"advice":{"ru":"Начни с волонтёрства рядом с домом: оно показывает, нравится ли тебе сама работа.","kk":"Үйіңнің жанындағы еріктіліктен баста: ол саған жұмыстың өзі ұнайтынын көрсетеді.","en":"Start with volunteering close to home: it shows whether you like the work itself."}}'::jsonb, '{"start":["small-town","no-support"],"interests":["social-impact","people"],"fears":["unknown-future","not-talented-enough"],"education":["university"],"challenges":["language","information"],"motives":["impact","belonging"],"decisions":["volunteering","mentor"],"transitions":["university-to-work"]}'::jsonb, '[]'::jsonb),
  ('demo-no-direction', 'demo', 'approved', 'en', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"У меня не было идей, поэтому я проводил маленькие эксперименты","kk":"Менде идея болмады, сондықтан шағын тәжірибелер жасадым","en":"I had no idea what I wanted, so I ran small experiments"},"categories":["unsure"],"ageRange":"18-24","before":{"ru":"Он закончил школу с хорошими оценками, но без любимого предмета. Казалось, что все вокруг знают свой путь.","kk":"Ол мектепті жақсы бағамен бітірді, бірақ сүйікті пәні болмады. Айналасындағылардың бәрі өз жолын білетіндей көрінді.","en":"He finished school with good grades and no favourite subject. Everyone around him seemed to know their path."},"challenges":{"ru":"Он чувствовал, что отстаёт, и переживал, что «не знать» означает, что с ним что-то не так.","kk":"Ол артта қалғандай сезінді және «білмеу» онымен бір нәрсе дұрыс емес дегенді білдіреді деп уайымдады.","en":"He felt behind and worried that not knowing meant something was wrong with him."},"turningPoint":{"ru":"Учитель предложил относиться к выбору как к лабораторной работе: за пять недель попробовать пять маленьких вещей и записывать, что чувствуешь после каждой.","kk":"Мұғалім таңдауға зертханалық жұмыс ретінде қарауды ұсынды: бес аптада бес шағын нәрсені байқап көріп, әрқайсысынан кейін не сезінгеніңді жазу.","en":"A teacher suggested treating the choice like a lab: try five small things in five weeks and write down how he felt after each."},"actions":{"ru":"Он попробовал обучающее занятие по программированию, разговор с медсестрой, смену волонтёром, короткий видеомонтаж и небольшую задачу с данными. Продолжить хотелось только задачу с данными.","kk":"Ол бағдарламалау бойынша оқу сабағын, медбикемен әңгімені, ерікті ретінде бір ауысымды, қысқа бейнемонтажды және деректермен шағын тапсырманы байқап көрді. Тек деректермен жұмысты жалғастырғысы келді.","en":"He tried a programming tutorial, a conversation with a nurse, a volunteer shift, a short video edit and a small data task. Only the data task made him want to continue."},"now":{"ru":"Сейчас он изучает анализ данных и по-прежнему проверяет новые идеи каждый семестр.","kk":"Қазір ол деректерді талдауды оқиды және әр семестр сайын жаңа идеяларды тексеруді жалғастырады.","en":"He now studies data analysis and still tests new ideas every term."},"advice":{"ru":"Направление легче увидеть после попыток, чем после долгих размышлений.","kk":"Бағытты ұзақ ойланудан гөрі байқап көргеннен кейін көру оңай.","en":"A direction is easier to see after trying than after long thinking."}}'::jsonb, '{"start":["big-city"],"interests":["tech","science"],"fears":["wrong-choice","unknown-future"],"education":["school","self-taught"],"challenges":["information","confidence"],"motives":["curiosity"],"decisions":["experiments","mentor"],"transitions":["school-to-university"]}'::jsonb, '[]'::jsonb),
  ('demo-at-27', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"В 27 лет я начал заново с программирования","kk":"27 жасымда бағдарламалаудан қайта бастадым","en":"At 27 I started again with programming"},"categories":["from-zero"],"ageRange":"25-34","before":{"ru":"Он четыре года работал бухгалтером в небольшой компании. Работа была стабильной, но каждое утро давалось тяжело.","kk":"Ол төрт жыл шағын компанияда бухгалтер болып жұмыс істеді. Жұмыс тұрақты болды, бірақ әр таң ауыр өтті.","en":"He worked for four years as an accountant at a small company. The job was stable, but every morning was hard."},"challenges":{"ru":"Он боялся, что в 27 лет уже поздно, и не хотел снова становиться студентом без дохода.","kk":"Ол 27 жаста кеш болды деп қорықты және қайтадан табыссыз студент болғысы келмеді.","en":"He was afraid that 27 was too late and did not want to become a student again with no income."},"turningPoint":{"ru":"Он автоматизировал отчёт простым скриптом и заметил, что весь вечер прошёл за этим занятием незаметно.","kk":"Ол есепті қарапайым скриптпен автоматтандырды және бүкіл кеш бұл іспен байқалмай өткенін аңғарды.","en":"He automated a report with a simple script and noticed that the whole evening had passed without him noticing."},"actions":{"ru":"Год он учился по вечерам на открытых курсах и делал маленькие проекты для своей же работы. Потом перешёл в отдел аналитики, а позже сменил компанию.","kk":"Ол бір жыл кешкілік ашық курстармен оқыды және өз жұмысына арналған шағын жобалар жасады. Кейін аналитика бөліміне ауысып, артынан компанияны ауыстырды.","en":"For a year he studied in the evenings with open courses and built small projects for his own job. Then he moved to an analytics team and later changed company."},"now":{"ru":"Сейчас он работает младшим разработчиком. По его словам, утро стало легче, хотя доход пока близок к прежнему.","kk":"Қазір ол кіші әзірлеуші болып жұмыс істейді. Оның айтуынша, таң жеңілдеді, бірақ табысы әзірге бұрынғыға жақын.","en":"He now works as a junior developer. He says mornings got easier, although his income is still close to what it was."},"advice":{"ru":"Не бросай всё сразу: работу можно менять шагами.","kk":"Бәрін бірден тастама: жұмысты қадаммен ауыстыруға болады.","en":"Do not quit everything at once: you can change your work step by step."}}'::jsonb, '{"start":["late-start"],"interests":["tech","business"],"fears":["too-late","money"],"education":["self-taught","university"],"challenges":["time","money"],"motives":["stability","curiosity"],"decisions":["gradual-change","side-project"],"transitions":["career-change","side-to-main"]}'::jsonb, '[]'::jsonb),
  ('demo-at-40', 'demo', 'approved', 'kk', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"40 жаста жаңа жолды бастадым","kk":"В 40 лет я начал новый путь","en":"At 40 I began a new path"},"categories":["from-zero"],"ageRange":"35-plus","before":{"ru":"Ол 15 жыл мектепте география пәнінен сабақ берді. Жұмысын жақсы көрді, бірақ жылдар өткен сайын өсу жоқ сияқты сезілді.","kk":"Он 15 лет преподавал географию в школе. Он любил работу, но с годами ему казалось, что роста нет.","en":"He taught geography at a school for 15 years. He loved the work but felt, as the years went by, that there was no room to grow."},"challenges":{"ru":"Отбасы мен жұмыс арасында уақыт аз болды, ал жасына байланысты «кеш емес пе?» деген ой мазалады.","kk":"Между семьёй и работой оставалось мало времени, а из-за возраста тревожила мысль: «не поздно ли?»","en":"There was little time between family and work, and his age made him worry: is it too late?"},"turningPoint":{"ru":"Мектепте оқушылармен экологиялық акция өткізді және мұны мамандық ретінде жалғастыруға болатынын түсінді.","kk":"Он провёл со школьниками экологическую акцию и понял, что это можно продолжить как профессию.","en":"He ran an environmental campaign with his students and realised it could become a profession."},"actions":{"ru":"Кешкілік онлайн курстар өтті, жергілікті экологиялық ұйымда ерікті болды, жұмысын тастамай жартылай күнге ауысты, кейін ұйымда жоба үйлестірушісі болды.","kk":"Он проходил вечерние онлайн-курсы, волонтёрил в местной экологической организации, не бросая работу перешёл на неполный день, а потом стал координатором проектов в организации.","en":"He took evening online courses, volunteered at a local environmental organisation, moved to part-time without quitting, and later became a project coordinator there."},"now":{"ru":"Қазір ол экологиялық білім беру жобаларын үйлестіреді; мұғалімдік тәжірибесі жұмысында көмектеседі.","kk":"Сейчас он координирует проекты по экологическому образованию, и опыт учителя помогает ему в работе.","en":"He now coordinates environmental education projects, and his teaching experience helps him in the job."},"advice":{"ru":"Бұрынғы тәжірибең босқа кетпейді, ол жаңа жолдың негізіне айналады.","kk":"Прежний опыт не пропадает: он становится основой нового пути.","en":"Your earlier experience is not wasted: it becomes the base of a new path."}}'::jsonb, '{"start":["late-start"],"interests":["nature","education"],"fears":["too-late","judgement"],"education":["university","self-taught"],"challenges":["time","confidence"],"motives":["impact","curiosity"],"decisions":["volunteering","gradual-change"],"transitions":["late-career-change","side-to-main"]}'::jsonb, '[]'::jsonb),
  ('demo-sports-referee', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"От спортивного судьи к организатору соревнований","kk":"Спорт төрешісінен жарыс ұйымдастырушысына дейін","en":"From sports referee to competition organiser"},"categories":["first-job","unexpected-passion"],"ageRange":"18-24","before":{"ru":"Он учился на IT и по выходным судил спортивные соревнования. Для него это было просто подработкой, а не профессией.","kk":"Ол IT мамандығында оқыды және демалыс күндері спорт жарыстарында төреші болды. Бұл оған кәсіп емес, жай қосымша жұмыс болып көрінді.","en":"He studied IT and on weekends officiated at sports competitions. To him it was a side job, not a profession."},"challenges":{"ru":"Два мира казались несвязанными, и он боялся, что придётся выбирать между ними.","kk":"Екі әлем бір-бірімен байланыссыз көрінді және ол екеуінің бірін таңдауға тура келеді деп қорықты.","en":"The two worlds seemed unrelated, and he feared he would have to choose between them."},"turningPoint":{"ru":"Организаторы турнира попросили помочь с регистрацией и таблицами результатов, и он написал для них простую систему.","kk":"Турнир ұйымдастырушылары тіркеуге және нәтиже кестелеріне көмектесуді өтінді, ол олар үшін қарапайым жүйе жазды.","en":"Tournament organisers asked him to help with registration and result tables, and he wrote them a simple system."},"actions":{"ru":"Он предложил автоматизировать протоколы, собрал отзывы судей и игроков и сделал ещё два проекта для других турниров.","kk":"Ол хаттамаларды автоматтандыруды ұсынды, төрешілер мен ойыншылардың пікірін жинап, басқа турнирлерге тағы екі жоба жасады.","en":"He proposed automating match records, gathered feedback from officials and players, and built two more projects for other tournaments."},"now":{"ru":"Параллельно с учёбой он делает инструменты для организации соревнований. Он понял, что необычные навыки можно соединять.","kk":"Оқумен қатар ол жарыстарды ұйымдастыруға арналған құралдар жасайды. Ол ерекше дағдыларды біріктіруге болатынын түсінді.","en":"Alongside his studies he builds tools for organising competitions. He learned that unusual skills can be combined."},"advice":{"ru":"Присмотрись к своим «побочным» занятиям: твоё место часто находится на стыке двух вещей.","kk":"«Қосымша» істеріңе мұқият қара: сенің орның жиі екі нәрсенің түйісінде болады.","en":"Look closely at your side activities: your place is often where two things meet."}}'::jsonb, '{"start":["big-city"],"interests":["sport","tech"],"fears":["wrong-choice","judgement"],"education":["university","self-taught"],"challenges":["time","information"],"motives":["recognition","curiosity"],"decisions":["side-project","experiments"],"transitions":["side-to-main","university-to-work"]}'::jsonb, '[]'::jsonb),
  ('demo-small-town-abroad', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"Из маленького города на учёбу за границу","kk":"Шағын қаладан шетелде оқуға","en":"From a small town to study abroad"},"categories":["study-abroad","education-journey"],"ageRange":"18-24","before":{"ru":"Он вырос в небольшом городе, где мало кто уезжал учиться за рубеж. Семья жила скромно.","kk":"Ол шетелге оқуға аз адам кететін шағын қалада өсті. Отбасы қарапайым өмір сүрді.","en":"He grew up in a small town where few people left to study abroad. His family lived modestly."},"challenges":{"ru":"Не хватало денег, английский был слабым, и не у кого было спросить совета.","kk":"Ақша жетіспеді, ағылшын тілі әлсіз еді және ақыл сұрайтын адам болмады.","en":"Money was short, his English was weak, and there was nobody to ask for advice."},"turningPoint":{"ru":"Он нашёл в интернете истории тех, кто поступал на стипендии, и понял, что это набор конкретных шагов, а не просто удача.","kk":"Ол интернеттен стипендияға түскендердің тарихын тауып, бұл жай сәттілік емес, нақты қадамдар жиынтығы екенін түсінді.","en":"He found stories online of people who won scholarships and realised it was a set of concrete steps, not just luck."},"actions":{"ru":"За два года он составил план: ежедневная практика английского, список стипендий с официальных сайтов и письма в университеты. Учитель помог ему с мотивационным письмом.","kk":"Екі жыл ішінде ол жоспар құрды: күн сайын ағылшын тілін жаттықтыру, ресми сайттардан стипендиялар тізімі және университеттерге хаттар. Мұғалім оған мотивациялық хатпен көмектесті.","en":"Over two years he made a plan: daily English practice, a list of scholarships from official sites and emails to universities. A teacher helped him with the motivation letter."},"now":{"ru":"Он поступил в университет за границей на стипендию и привыкает к новому языку и городу. Первые месяцы было одиноко.","kk":"Ол шетелдегі университетке стипендиямен түсті және жаңа тіл мен қалаға үйреніп жатыр. Алғашқы айларда жалғыз болды.","en":"He was admitted to a university abroad with a scholarship and is getting used to a new language and city. The first months were lonely."},"advice":{"ru":"Раздели большую цель на шаги и сделай самый маленький сегодня.","kk":"Үлкен мақсатты қадамдарға бөл және бүгін ең кішкентайын жаса.","en":"Break a big goal into steps and take the smallest one today."}}'::jsonb, '{"start":["small-town","low-income","no-support"],"interests":["science","languages-culture"],"fears":["money","not-talented-enough"],"education":["school","abroad-study"],"challenges":["money","language","information"],"motives":["freedom","curiosity"],"decisions":["mentor","move-abroad"],"transitions":["school-to-university","relocation"]}'::jsonb, '[]'::jsonb),
  ('demo-pause-and-return', 'demo', 'approved', 'ru', null, null, '{"ru":"Демонстрационный пример (вымышлен)","kk":"Демонстрациялық мысал (ойдан шығарылған)","en":"Demonstration example (fictional)"}'::jsonb, null, '{"title":{"ru":"Я бросила университет, а потом вернулась","kk":"Мен университетті тастап, кейін қайтып оралдым","en":"I left university and then came back"},"categories":["failed-restart","changed-major","education-journey"],"ageRange":"18-24","before":{"ru":"Она поступила на экономику по совету родственников и на втором курсе выгорела.","kk":"Ол туыстарының кеңесімен экономикаға түсіп, екінші курста әбден шаршады.","en":"She enrolled in economics on her relatives'' advice and burned out in the second year."},"challenges":{"ru":"Бессонные ночи, чувство, что она не справляется, и стыд перед семьёй.","kk":"Ұйқысыз түндер, істей алмай жатырмын деген сезім және отбасының алдындағы ұят.","en":"Sleepless nights, a feeling that she could not cope, and shame in front of her family."},"turningPoint":{"ru":"Она взяла академический отпуск и сказала себе, что цель этой паузы отдохнуть и разобраться, а не что-то доказать.","kk":"Ол академиялық демалыс алып, бұл үзілістің мақсаты — демалу және түсіну, ештеңені дәлелдеу емес деп өзіне айтты.","en":"She took academic leave and told herself the goal of the break was to rest and figure things out, not to prove anything."},"actions":{"ru":"Полгода она подрабатывала, вела блог о своих мыслях, ходила к психологу в студенческий центр и пробовала разные занятия. Потом вернулась и перевелась на журналистику.","kk":"Жарты жыл ол қосымша жұмыс істеді, ойлары туралы блог жүргізді, студенттік орталықтағы психологқа барды және әртүрлі істерді байқап көрді. Кейін оралып, журналистикаға ауысты.","en":"For six months she worked part-time, kept a blog about her thoughts, saw a psychologist at the student centre and tried different activities. Then she came back and transferred to journalism."},"now":{"ru":"Сейчас она учится на журналистике и пишет для университетского издания. Она знает, что отдых был нужен.","kk":"Қазір ол журналистикада оқиды және университет басылымына жазады. Демалыстың қажет болғанын біледі.","en":"She now studies journalism and writes for a university publication. She knows the rest was necessary."},"advice":{"ru":"Пауза не провал, если у неё есть цель: отдохнуть и подумать.","kk":"Егер үзілістің мақсаты бар болса, ол сәтсіздік емес: демалу және ойлану.","en":"A pause is not a failure if it has a purpose: to rest and think."}}'::jsonb, '{"start":["family-pressure","big-city"],"interests":["creative","languages-culture"],"fears":["failure","judgement"],"education":["university","dropped-out","changed-major"],"challenges":["burnout","family"],"motives":["freedom","recognition"],"decisions":["take-a-break","switch-major"],"transitions":["gap-year","major-change"]}'::jsonb, '[]'::jsonb)
insert into public.experiments (id, direction, difficulty, content) values
  ('exp-diplomacy-memo', 'diplomacy', 'medium', '{"title":{"ru":"Мини-записка по международному вопросу","kk":"Халықаралық мәселе бойынша шағын жазба","en":"One-page brief on an international issue"},"steps":{"ru":["Выбери один текущий международный вопрос, который тебе интересен.","Прочитай два источника из разных стран или с разными позициями и выпиши аргументы каждой стороны.","Напиши записку на одну страницу: суть вопроса, позиции сторон, возможные компромиссы.","Объясни её другу за три минуты и спроси, что осталось непонятным."],"kk":["Өзіңе қызықты бір өзекті халықаралық мәселені таңда.","Әртүрлі елдерден немесе әртүрлі позициядағы екі дереккөзді оқып, әр тараптың дәлелдерін жаз.","Бір беттік жазба жаз: мәселенің мәні, тараптардың позициялары, мүмкін келісімдер.","Оны досыңа үш минутта түсіндіріп, не түсініксіз қалғанын сұра."],"en":["Pick one current international issue that interests you.","Read two sources from different countries or with different positions and note each side''s arguments.","Write a one-page brief: the issue, each side''s position, possible compromises.","Explain it to a friend in three minutes and ask what remained unclear."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Сайт un.org (раздел новостей)","Новости двух разных изданий по одной теме"],"kk":["un.org сайты (жаңалықтар бөлімі)","Бір тақырып бойынша екі түрлі басылымның жаңалықтары"],"en":["The un.org website (news section)","News from two different outlets on the same topic"]},"outcome":{"ru":"Записка на одну страницу и опыт объяснения сложной темы простыми словами.","kk":"Бір беттік жазба және күрделі тақырыпты қарапайым сөзбен түсіндіру тәжірибесі.","en":"A one-page brief and practice explaining a complex topic in plain words."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно понимать позицию противоположной стороны?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қарсы тараптың позициясын түсіну қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to understand the opposite side''s position?"]}}'::jsonb),
  ('exp-entrepreneurship-test', 'entrepreneurship', 'hard', '{"title":{"ru":"Проверь идею на пяти людях","kk":"Идеяңды бес адамда тексер","en":"Test an idea on five people"},"steps":{"ru":["Сформулируй одну проблему, которую можно решить небольшим продуктом или услугой.","Поговори минимум с пятью людьми, у которых эта проблема есть: как они решают её сейчас?","Предложи одному человеку простейшее решение за небольшую плату или в обмен на отзыв.","Запиши, что узнал о клиентах и о себе в роли продавца."],"kk":["Шағын өніммен немесе қызметпен шешуге болатын бір мәселені тұжырымда.","Осы мәселесі бар кемінде бес адаммен сөйлес: олар қазір оны қалай шешеді?","Бір адамға ең қарапайым шешімді аз ақыға немесе пікір үшін ұсын.","Клиенттер және сатушы ретінде өзің туралы не білгеніңді жаз."],"en":["State one problem that a small product or service could solve.","Talk to at least five people who have this problem: how do they solve it today?","Offer one person the simplest solution for a small fee or in exchange for feedback.","Write down what you learned about customers and about yourself as a seller."]},"timeEstimate":{"ru":"6–8 ч за неделю","kk":"Апта ішінде 6–8 сағ","en":"6–8 h over a week"},"resources":{"ru":["Google Forms или обычный блокнот для заметок","Один знакомый, который сам что-то продавал"],"kk":["Google Forms немесе қарапайым жазба дәптері","Өзі бір нәрсе сатып көрген бір таныс"],"en":["Google Forms or a plain notebook for notes","One acquaintance who has sold something"]},"outcome":{"ru":"Проверенная или опровергнутая гипотеза и первое впечатление от общения с клиентами.","kk":"Расталған немесе жоққа шығарылған болжам және клиенттермен сөйлесудің алғашқы әсері.","en":"A confirmed or rejected hypothesis and a first feel for talking to customers."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли комфортно предлагать и слышать «нет»?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Ұсыну және «жоқ» деген жауап есту ыңғайлы болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it comfortable to offer something and hear no?"]}}'::jsonb),
  ('exp-psychology-diary', 'psychology', 'easy', '{"title":{"ru":"Неделя наблюдений за своими привычками","kk":"Өз әдеттерің бойынша бір апталық бақылау","en":"A week of observing your own habits"},"steps":{"ru":["Выбери одну привычку, например сон, телефон или откладывание дел.","Семь дней записывай по пять строк: что произошло, что ты почувствовал, что сделал.","Найди и прочитай одну популярную статью по теме и сравни с тем, что заметил.","Сделай три вывода и отметь, что в них факт, а что догадка."],"kk":["Бір әдетті таңда, мысалы ұйқы, телефон немесе істерді кейінге қалдыру.","Жеті күн бойы бес жолдан жаз: не болды, не сездің, не істедің.","Тақырып бойынша бір танымал мақаланы тауып оқы және өз байқағандарыңмен салыстыр.","Үш қорытынды жаса және олардың қайсысы факт, қайсысы болжам екенін белгіле."],"en":["Pick one habit, for example sleep, phone use or procrastination.","For seven days write five lines: what happened, what you felt, what you did.","Find and read one popular article on the topic and compare it with what you noticed.","Write three conclusions and mark which are facts and which are guesses."]},"timeEstimate":{"ru":"10–15 мин в день, 7 дней","kk":"Күніне 10–15 мин, 7 күн","en":"10–15 min a day for 7 days"},"resources":{"ru":["Блокнот или заметки в телефоне","Одна статья с понятным списком источников"],"kk":["Дәптер немесе телефондағы жазбалар","Дереккөздер тізімі нақты бір мақала"],"en":["A notebook or phone notes","One article with a clear list of sources"]},"outcome":{"ru":"Дневник наблюдений и практика отличать факты от догадок.","kk":"Бақылау күнделігі және фактіні болжамнан ажырату тәжірибесі.","en":"An observation log and practice separating facts from guesses."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно разбираться в причинах поведения, а не только замечать его?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Мінез-құлықты тек байқау емес, оның себептерін түсіну қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you enjoy digging into the causes of behaviour rather than just noticing it?"]}}'::jsonb),
  ('exp-programming-first', 'programming', 'easy', '{"title":{"ru":"Первая маленькая программа","kk":"Алғашқы шағын бағдарлама","en":"Your first small program"},"steps":{"ru":["Пройди первое занятие курса CS50x или любого вводного курса по программированию.","Придумай крошечную задачу из жизни, например счётчик расходов или шуточный тест.","Напиши программу, которая её решает, даже если она получится неидеальной.","Покажи результат другу и запиши, на каких местах застрял."],"kk":["CS50x курсының алғашқы сабағын немесе кез келген кіріспе бағдарламалау курсын өт.","Өмірден өте кішкентай тапсырма ойлап тап, мысалы шығын санағышы немесе әзіл тест.","Оны шешетін бағдарлама жаз, ол кемелсіз болса да.","Нәтижені досыңа көрсетіп, қай жерлерде тұрып қалғаныңды жаз."],"en":["Complete the first lesson of CS50x or any introductory programming course.","Come up with a tiny real-life task, such as an expense counter or a fun quiz.","Write a program that solves it, even if it is imperfect.","Show the result to a friend and write down where you got stuck."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["cs50.harvard.edu/x (бесплатный курс)","Любой бесплатный онлайн-редактор кода"],"kk":["cs50.harvard.edu/x (тегін курс)","Кез келген тегін онлайн код редакторы"],"en":["cs50.harvard.edu/x (free course)","Any free online code editor"]},"outcome":{"ru":"Работающая маленькая программа и понимание, как ощущается процесс программирования.","kk":"Жұмыс істейтін шағын бағдарлама және бағдарламалау процесінің қандай екенін түсіну.","en":"A working small program and a sense of what programming feels like."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе искать ошибки и разбираться, почему не работает?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қателерді іздеу және неге жұмыс істемейтінін түсіну ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like hunting for errors and figuring out why something does not work?"]}}'::jsonb),
  ('exp-design-redo', 'design', 'easy', '{"title":{"ru":"Переделай один неудобный экран","kk":"Бір ыңғайсыз экранды қайта жаса","en":"Redesign one awkward screen"},"steps":{"ru":["Выбери экран приложения или сайта, которым неудобно пользоваться, и запиши три проблемы.","Нарисуй на бумаге свой вариант решения.","Перерисуй его в бесплатном редакторе, например Figma или Canva.","Покажи двум людям и спроси, что им понятно, а что нет."],"kk":["Пайдалануға ыңғайсыз қосымша немесе сайт экранын таңда да, үш мәселесін жаз.","Шешімнің өз нұсқасын қағазға сыз.","Оны тегін редакторда қайта сыз, мысалы Figma немесе Canva.","Екі адамға көрсетіп, нені түсінетінін, нені түсінбейтінін сұра."],"en":["Pick an app or website screen that is awkward to use and write down three problems.","Sketch your own solution on paper.","Redraw it in a free editor such as Figma or Canva.","Show it to two people and ask what is clear and what is not."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["figma.com (бесплатный тариф)","canva.com"],"kk":["figma.com (тегін тариф)","canva.com"],"en":["figma.com (free plan)","canva.com"]},"outcome":{"ru":"Эскиз и редизайн экрана с отзывами от двух людей.","kk":"Эскиз және екі адамның пікірі бар экранның қайта дизайны.","en":"A sketch and a redesigned screen with feedback from two people."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе принимать критику и менять работу по отзывам?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Сынды қабылдап, жұмысты пікірге қарай өзгерту ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like taking critique and changing the work in response?"]}}'::jsonb),
  ('exp-education-mini-lesson', 'education', 'easy', '{"title":{"ru":"Проведи мини-урок","kk":"Шағын сабақ өткіз","en":"Teach a mini lesson"},"steps":{"ru":["Выбери навык, которым владеешь, и сформулируй цель урока одним предложением.","Подготовь план на 15–20 минут с одним примером и одним упражнением.","Проведи урок для друга, младшего брата или сестры.","Спроси, что было понятно, а что нет, и запиши, что бы изменил."],"kk":["Өзің білетін дағдыны таңда және сабақтың мақсатын бір сөйлеммен тұжырымда.","Бір мысалы және бір жаттығуы бар 15–20 минуттық жоспар дайында.","Сабақты досыңа, інісіне немесе қарындасыңа өткіз.","Не түсінікті, не түсініксіз болғанын сұрап, нені өзгертетініңді жаз."],"en":["Choose a skill you have and state the goal of the lesson in one sentence.","Prepare a 15–20 minute plan with one example and one exercise.","Teach it to a friend or a younger sibling.","Ask what was clear and what was not, and note what you would change."]},"timeEstimate":{"ru":"2 ч","kk":"2 сағ","en":"2 h"},"resources":{"ru":["Лист бумаги или доска","Один готовый ученик, который согласен быть тестовым"],"kk":["Қағаз парағы немесе тақта","Сынақ оқушысы болуға келісетін бір адам"],"en":["A sheet of paper or a whiteboard","One willing learner to test on"]},"outcome":{"ru":"План мини-урока и первый опыт объяснения другому человеку.","kk":"Шағын сабақ жоспары және басқа адамға түсіндірудің алғашқы тәжірибесі.","en":"A mini-lesson plan and a first experience of explaining to someone."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Радовало ли тебя, когда другой человек наконец понимал?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Басқа адам ақыры түсінгенде қуандың ба?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did it feel good when the other person finally understood?"]}}'::jsonb),
  ('exp-media-interview', 'media', 'medium', '{"title":{"ru":"Короткое интервью и материал","kk":"Қысқа сұхбат және материал","en":"A short interview and a piece"},"steps":{"ru":["Выбери человека, чья работа тебе интересна, и подготовь пять вопросов.","Проведи интервью на 15 минут, записав его с разрешения собеседника.","Напиши текст на 300 слов или смонтируй видео на две минуты.","Покажи результат собеседнику, чтобы проверить факты, и одному читателю."],"kk":["Жұмысы саған қызық адамды таңда және бес сұрақ дайында.","Әңгімелесушінің рұқсатымен жазып, 15 минуттық сұхбат жүргіз.","300 сөздік мәтін жаз немесе екі минуттық бейне монтажда.","Фактілерді тексеру үшін нәтижені әңгімелесушіге және бір оқырманға көрсет."],"en":["Choose a person whose work interests you and prepare five questions.","Interview them for 15 minutes, recording with their permission.","Write a 300-word text or edit a two-minute video.","Show the result to your interviewee to check facts, and to one reader."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Диктофон в телефоне","Любой бесплатный видеоредактор"],"kk":["Телефондағы диктофон","Кез келген тегін бейне редактор"],"en":["The voice recorder on your phone","Any free video editor"]},"outcome":{"ru":"Готовый короткий материал и понимание, как устроена работа с источниками.","kk":"Дайын қысқа материал және дереккөздермен жұмыс қалай ұйымдастырылатынын түсіну.","en":"A finished short piece and an idea of how working with sources goes."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе слушать людей и превращать услышанное в текст?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Адамдарды тыңдап, естігеніңді мәтінге айналдыру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like listening to people and turning it into a text?"]}}'::jsonb),
  ('exp-research-mini-survey', 'research', 'medium', '{"title":{"ru":"Мини-исследование на десяти людях","kk":"Он адамға арналған шағын зерттеу","en":"A mini study with ten people"},"steps":{"ru":["Сформулируй один вопрос, на который хочется найти ответ, например про привычки студентов.","Составь анкету из пяти вопросов в Google Forms.","Собери минимум десять ответов и посчитай простые итоги.","Напиши полстраницы выводов и отдельно отметь, чего выборка из десяти человек не доказывает."],"kk":["Жауабын табуды қалайтын бір сұрақты тұжырымда, мысалы студенттердің әдеттері туралы.","Google Forms-та бес сұрақтан тұратын сауалнама жаса.","Кемінде он жауап жинап, қарапайым қорытындыларды есепте.","Жарты бет қорытынды жаз да, он адамдық таңдау нені дәлелдемейтінін бөлек белгіле."],"en":["State one question you want answered, for example about student habits.","Make a five-question survey in Google Forms.","Collect at least ten answers and calculate simple results.","Write half a page of findings and note separately what a sample of ten does not prove."]},"timeEstimate":{"ru":"3–5 ч","kk":"3–5 сағ","en":"3–5 h"},"resources":{"ru":["Google Forms","Таблица для подсчёта ответов"],"kk":["Google Forms","Жауаптарды есептеуге арналған кесте"],"en":["Google Forms","A spreadsheet for counting answers"]},"outcome":{"ru":"Мини-отчёт и понимание, насколько осторожно нужно делать выводы.","kk":"Шағын есеп және қорытындыны қаншалықты сақтықпен жасау керектігін түсіну.","en":"A mini report and a sense of how careful conclusions must be."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно искать ответ там, где его нет в готовом виде?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Жауабы дайын жоқ жерден оны іздеу қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to look for an answer that does not exist ready-made?"]}}'::jsonb),
  ('exp-social-impact-shift', 'social-impact', 'easy', '{"title":{"ru":"Одна смена волонтёрства","kk":"Бір ауысым еріктілік","en":"One volunteering shift"},"steps":{"ru":["Найди местную организацию или инициативу, которой нужны волонтёры, и напиши ей.","Приди на одну смену и выполни то, о чём попросят.","Спроси координатора, какие навыки здесь нужнее всего и как он сам сюда пришёл.","Запиши, что было неожиданного и какой эффект ты увидел сам."],"kk":["Еріктілер қажет жергілікті ұйымды немесе бастаманы тауып, оған жаз.","Бір ауысымға келіп, сұраған істі орында.","Үйлестірушіден мұнда қандай дағдылар көбірек қажет екенін және өзі мұнда қалай келгенін сұра.","Не күтпеген болғанын және өзің қандай әсер көргеніңді жаз."],"en":["Find a local organisation or initiative that needs volunteers and write to them.","Come to one shift and do what they ask.","Ask the coordinator which skills matter most here and how they got started.","Write down what was unexpected and what effect you saw yourself."]},"timeEstimate":{"ru":"3–4 ч, не считая дороги","kk":"3–4 сағ, жолды қоспағанда","en":"3–4 h, not counting travel"},"resources":{"ru":["Страницы местных организаций в соцсетях","unv.org и другие платформы для волонтёров"],"kk":["Жергілікті ұйымдардың әлеуметтік желідегі беттері","unv.org және еріктілерге арналған басқа платформалар"],"en":["Social media pages of local organisations","unv.org and other volunteering platforms"]},"outcome":{"ru":"Первый опыт участия и список навыков, которые пригодились.","kk":"Қатысудың алғашқы тәжірибесі және пайдасы тиген дағдылар тізімі.","en":"A first taste of taking part and a list of skills that proved useful."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли приятно именно участие, а не то, как это выглядит со стороны?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Тек сырттан қалай көрінетіні емес, қатысудың өзі ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you enjoy the participation itself rather than how it looks from outside?"]}}'::jsonb),
  ('exp-medicine-conversation', 'medicine', 'medium', '{"title":{"ru":"Разговор с медицинским работником и курс первой помощи","kk":"Медицина қызметкерімен әңгіме және алғашқы көмек курсы","en":"A conversation with a health worker and a first-aid lesson"},"steps":{"ru":["Подготовь восемь вопросов о работе: что нравится, что тяжело, как выглядит обычный день.","Поговори 20 минут с медсестрой, врачом или фельдшером, которого знаешь или которого тебе порекомендуют.","Пройди короткий видеоурок или курс по основам первой помощи.","Запиши, что тебя привлекло, а что отпугнуло, и обсуди с кем-то из близких."],"kk":["Жұмыс туралы сегіз сұрақ дайында: не ұнайды, не қиын, қарапайым күн қалай өтеді.","Өзің танитын немесе саған ұсынылған мейірбикемен, дәрігермен немесе фельдшермен 20 минут сөйлес.","Алғашқы көмек негіздері бойынша қысқа бейнесабақ немесе курс өт.","Сені не тартқанын, не үркіткенін жазып, жақындарыңның біреуімен талқыла."],"en":["Prepare eight questions about the job: what they like, what is hard, what a normal day looks like.","Talk for 20 minutes with a nurse, doctor or paramedic you know or are introduced to.","Take a short video lesson or course on first-aid basics.","Write down what attracted you and what put you off, and discuss it with someone close."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Знакомые или родственники, работающие в медицине","Бесплатные видеоуроки по первой помощи"],"kk":["Медицинада жұмыс істейтін таныстар немесе туыстар","Алғашқы көмек бойынша тегін бейнесабақтар"],"en":["Acquaintances or relatives who work in healthcare","Free first-aid video lessons"]},"outcome":{"ru":"Более реалистичная картина повседневной работы в медицине.","kk":"Медицинадағы күнделікті жұмыстың нақтырақ көрінісі.","en":"A more realistic picture of everyday work in healthcare."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Привлекает ли тебя сама рутина работы с людьми в сложных ситуациях?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қиын жағдайдағы адамдармен жұмыстың күнделікті жұмысы сені тарта ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Are you drawn to the daily routine of working with people in hard situations?"]}}'::jsonb),
  ('exp-law-plain-language', 'law', 'medium', '{"title":{"ru":"Разбор одного договора простым языком","kk":"Бір шартты қарапайым тілмен талдау","en":"Explain one contract in plain language"},"steps":{"ru":["Возьми обычный документ, например типовой договор аренды или пользовательское соглашение.","Отметь пункты, которые непонятны или кажутся рискованными.","Найди в официальных источниках, что говорит закон по двум-трём таким вопросам.","Перескажи документ простым языком на одной странице и покажи человеку, знающему право, если есть такая возможность."],"kk":["Қарапайым құжатты ал, мысалы жалдаудың үлгілік шартын немесе пайдаланушы келісімін.","Түсініксіз немесе қауіпті көрінетін тармақтарды белгіле.","Осындай екі-үш мәселе бойынша заң не дейтінін ресми дереккөздерден тап.","Құжатты қарапайым тілмен бір бетте қайта айтып, мүмкіндік болса, құқықты білетін адамға көрсет."],"en":["Take an everyday document, such as a standard rental agreement or terms of service.","Mark the clauses that are unclear or look risky.","Look up in official sources what the law says about two or three of these points.","Retell the document in plain language on one page and, if possible, show it to someone who knows the law."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["Официальные базы законодательства твоей страны","Любой типовой договор из открытых источников"],"kk":["Еліңдегі заңнаманың ресми базалары","Ашық дереккөздердегі кез келген үлгілік шарт"],"en":["Official legislation databases in your country","Any template contract from open sources"]},"outcome":{"ru":"Страница с разбором документа и понимание, как читаются юридические тексты.","kk":"Құжат талдауы бар бет және заң мәтіндері қалай оқылатынын түсіну.","en":"A page analysing a document and a feel for how legal texts are read."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе внимательно читать мелкий текст и искать неточности?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Ұсақ мәтінді мұқият оқып, дәлсіздіктерді іздеу ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like reading fine print closely and looking for gaps?"]}}'::jsonb),
  ('exp-engineering-paper-bridge', 'engineering', 'easy', '{"title":{"ru":"Бумажный мост и испытание нагрузкой","kk":"Қағаз көпір және жүктемемен сынау","en":"A paper bridge and a load test"},"steps":{"ru":["Сделай мост пролётом около 20 см только из бумаги и скотча.","Постепенно клади на него монетки и запиши, сколько он выдержал.","Измени одну деталь, например форму или складки, и повтори испытание.","Сравни результаты и объясни, почему вторая версия работает лучше или хуже."],"kk":["Тек қағаз бен скотчтан шамамен 20 см аралықты көпір жаса.","Үстіне біртіндеп тиындар қойып, қанша көтергенін жаз.","Бір бөлшекті, мысалы пішінді немесе бүктемелерді өзгертіп, сынауды қайтала.","Нәтижелерді салыстырып, екінші нұсқаның неге жақсы немесе нашар жұмыс істейтінін түсіндір."],"en":["Build a bridge about 20 cm long from paper and tape only.","Gradually place coins on it and note how many it held.","Change one detail, such as the shape or folds, and test again.","Compare the results and explain why the second version works better or worse."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["Бумага, скотч, монеты","Учебник физики за школьный курс"],"kk":["Қағаз, скотч, тиындар","Мектеп курсының физика оқулығы"],"en":["Paper, tape, coins","A school physics textbook"]},"outcome":{"ru":"Две версии конструкции, таблица результатов и объяснение разницы.","kk":"Құрылымның екі нұсқасы, нәтиже кестесі және айырмашылық түсіндірмесі.","en":"Two versions of a structure, a results table and an explanation of the difference."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе переделывать, измерять и снова проверять?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қайта жасау, өлшеу және қайта тексеру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like redoing, measuring and testing again?"]}}'::jsonb),
  ('exp-data-first-analysis', 'data-ml', 'medium', '{"title":{"ru":"Первый анализ данных","kk":"Деректердің алғашқы талдауы","en":"Your first data analysis"},"steps":{"ru":["Возьми небольшой набор данных: свой журнал сна или расходов либо открытый набор с kaggle.com/datasets.","Посчитай среднее, минимум и максимум и построй один график в таблице или Python.","Запиши три вывода и отметь, какие из них можно проверить дальше.","Если хочется больше, пройди первый урок курса «Intro to Machine Learning» на kaggle.com/learn."],"kk":["Шағын деректер жиынын ал: өз ұйқы немесе шығын журналыңды не kaggle.com/datasets сайтындағы ашық жиынды.","Орташа, ең кіші және ең үлкен мәнді есепте және кестеде немесе Python-да бір график сал.","Үш қорытынды жазып, олардың қайсысын әрі қарай тексеруге болатынын белгіле.","Көбірек қаласаң, kaggle.com/learn сайтындағы «Intro to Machine Learning» курсының алғашқы сабағын өт."],"en":["Take a small dataset: your own sleep or spending log, or an open one from kaggle.com/datasets.","Calculate the average, minimum and maximum and make one chart in a spreadsheet or Python.","Write three conclusions and mark which ones can be tested further.","If you want more, take the first lesson of the Intro to Machine Learning course at kaggle.com/learn."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["kaggle.com/datasets и kaggle.com/learn","Google Sheets или любая электронная таблица"],"kk":["kaggle.com/datasets және kaggle.com/learn","Google Sheets немесе кез келген электрондық кесте"],"en":["kaggle.com/datasets and kaggle.com/learn","Google Sheets or any spreadsheet"]},"outcome":{"ru":"Один график, три вывода и первое ощущение от работы с данными.","kk":"Бір график, үш қорытынды және деректермен жұмыстың алғашқы сезімі.","en":"One chart, three conclusions and a first feel for working with data."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно искать закономерности даже тогда, когда ответ получался скучным?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Жауап жалықтырарлық болса да, заңдылықтарды іздеу қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to look for patterns even when the answer was dull?"]}}'::jsonb),
  ('exp-environment-audit', 'environment', 'easy', '{"title":{"ru":"Экоаудит одного места","kk":"Бір жердің экологиялық аудиті","en":"An eco-audit of one place"},"steps":{"ru":["Выбери одно место: свой двор, класс или кухню.","Неделю записывай, сколько и какого мусора там появляется, и снимай фото.","Предложи три конкретных изменения и оцени, что из этого реально выполнить.","Расскажи свой план тем, кто пользуется этим местом, и попробуй одно изменение."],"kk":["Бір жерді таңда: өз аулаңды, сыныбыңды немесе асүйіңді.","Бір апта бойы онда қандай және қанша қоқыс пайда болатынын жазып, фотоға түсір.","Үш нақты өзгеріс ұсынып, олардың қайсысын нақты орындауға болатынын бағала.","Жоспарыңды сол жерді пайдаланатындарға айтып, бір өзгерісті байқап көр."],"en":["Choose one place: your yard, classroom or kitchen.","For a week, note how much and what kind of waste appears there and take photos.","Propose three concrete changes and judge which are realistic.","Present the plan to the people who use the place and try one change."]},"timeEstimate":{"ru":"10 мин в день, 7 дней, плюс 1 ч","kk":"Күніне 10 мин, 7 күн, қосымша 1 сағ","en":"10 min a day for 7 days, plus 1 h"},"resources":{"ru":["Блокнот и камера телефона","Местные правила раздельного сбора отходов"],"kk":["Дәптер және телефон камерасы","Қалдықтарды бөлек жинаудың жергілікті ережелері"],"en":["A notebook and your phone camera","Local rules on waste sorting"]},"outcome":{"ru":"Короткий план улучшений и опыт убеждать людей, а не только замечать проблему.","kk":"Жақсартулардың қысқа жоспары және мәселені тек байқау емес, адамдарды сендіру тәжірибесі.","en":"A short improvement plan and practice persuading people, not just spotting a problem."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе превращать наблюдения в конкретные действия?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Бақылауларды нақты әрекетке айналдыру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like turning observations into concrete actions?"]}}'::jsonb)
insert into public.opportunities (id, name, kind, levels, country, cost, description, eligibility, url, deadline, verified_at, status) values
  ('bolashak', 'Bolashak (Болашак)', 'scholarship', '{master,phd}'::text[], 'international', 'unknown', '{"ru":"Международная стипендия правительства Казахстана для обучения и научных стажировок за рубежом. Программу ведёт Центр международных программ.","kk":"Қазақстан Үкіметінің шетелде оқуға және ғылыми тағылымдамадан өтуге арналған халықаралық стипендиясы. Бағдарламаны Халықаралық бағдарламалар орталығы жүргізеді.","en":"An international scholarship of the Government of Kazakhstan for study and research internships abroad, run by the Center for International Programs."}'::jsonb, '{"ru":"Для граждан Казахстана. Требования к уровню образования, языку и опыту работы уточняйте на официальном сайте.","kk":"Қазақстан азаматтарына арналған. Білім деңгейі, тіл және жұмыс тәжірибесі талаптарын ресми сайттан нақтылаңыз.","en":"For citizens of Kazakhstan. Check the education, language and work-experience requirements on the official website."}'::jsonb, 'https://bolashak.gov.kz', null::date, null::date, 'unverified'),
  ('erasmus-plus', 'Erasmus+', 'exchange', '{bachelor,master,phd}'::text[], 'europe', 'unknown', '{"ru":"Программа Европейского союза в сфере образования, обучения, молодёжи и спорта. Включает обмены студентов, стажировки и совместные магистерские программы.","kk":"Еуропалық Одақтың білім беру, оқыту, жастар және спорт саласындағы бағдарламасы. Студенттер алмасуын, тағылымдамаларды және бірлескен магистратура бағдарламаларын қамтиды.","en":"The European Union programme for education, training, youth and sport. It includes student exchanges, traineeships and joint master''s programmes."}'::jsonb, '{"ru":"Возможности для жителей стран-партнёров, включая Казахстан, зависят от конкретного направления. Условия и сроки уточняйте на официальном сайте.","kk":"Әріптес елдердің, соның ішінде Қазақстанның тұрғындарына қолжетімділік нақты бағытқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Access for residents of partner countries, including Kazakhstan, depends on the specific action. Check conditions and deadlines on the official website."}'::jsonb, 'https://erasmus-plus.ec.europa.eu', null::date, null::date, 'unverified'),
  ('daad', 'DAAD', 'scholarship', '{master,phd}'::text[], 'germany', 'unknown', '{"ru":"Немецкая служба академических обменов: стипендии, а также портал Study Guide Germany для иностранных студентов.","kk":"Неміс академиялық алмасу қызметі: стипендиялар және шетелдік студенттерге арналған Study Guide Germany порталы.","en":"The German Academic Exchange Service: scholarships plus the Study Guide Germany platform for international students."}'::jsonb, '{"ru":"Набор стипендий большой, у каждой свои условия. Условия и сроки уточняйте на официальном сайте.","kk":"Стипендиялар көп, әрқайсысының өз шарттары бар. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"There are many scholarships, each with its own conditions. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.daad.de/en/', null::date, null::date, 'unverified'),
  ('chevening', 'Chevening', 'scholarship', '{master}'::text[], 'uk', 'unknown', '{"ru":"Стипендия правительства Великобритании для одногодичной магистратуры в британских университетах.","kk":"Ұлыбритания Үкіметінің Британ университеттерінде бір жылдық магистратурада оқуға арналған стипендиясы.","en":"A UK government scholarship for a one-year master''s degree at a UK university."}'::jsonb, '{"ru":"Нужно быть гражданином страны, где действует программа. Условия и сроки уточняйте на официальном сайте.","kk":"Бағдарлама жұмыс істейтін елдің азаматы болу керек. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"You must be a citizen of a country where the programme operates. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.chevening.org', null::date, null::date, 'unverified'),
  ('fulbright-foreign-student', 'Fulbright Foreign Student Program', 'scholarship', '{master,phd}'::text[], 'usa', 'unknown', '{"ru":"Программа правительства США, которая позволяет гражданам других стран учиться в США. Заявка подаётся через Фулбрайтовскую комиссию, фонд или посольство США в своей стране.","kk":"АҚШ Үкіметінің басқа ел азаматтарына АҚШ-та оқуға мүмкіндік беретін бағдарламасы. Өтінім өз еліңдегі Фулбрайт комиссиясы, қор немесе АҚШ елшілігі арқылы беріледі.","en":"A US government programme that lets citizens of other countries study in the United States. Applications go through the Fulbright Commission, foundation or US Embassy in your home country."}'::jsonb, '{"ru":"Условия и сроки уточняйте на официальном сайте.","kk":"Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Check conditions and deadlines on the official website."}'::jsonb, 'https://foreign.fulbrightonline.org', null::date, null::date, 'unverified'),
  ('stipendium-hungaricum', 'Stipendium Hungaricum', 'scholarship', '{bachelor,master,phd}'::text[], 'hungary', 'unknown', '{"ru":"Государственная стипендия Венгрии для иностранных студентов в венгерских университетах.","kk":"Венгрия Үкіметінің шетелдік студенттерге арналған, Венгрия университеттерінде оқуға берілетін стипендиясы.","en":"A Hungarian government scholarship for international students at Hungarian universities."}'::jsonb, '{"ru":"Приём идёт по учебным годам; на сайте указано, открыт ли набор. Условия и сроки уточняйте на официальном сайте.","kk":"Қабылдау оқу жылдары бойынша өтеді; сайтта қабылдау ашық немесе жабық екені көрсетіледі. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Applications run by academic year; the site shows whether admission is open. Check conditions and deadlines on the official website."}'::jsonb, 'https://stipendiumhungaricum.hu', null::date, null::date, 'unverified'),
  ('turkiye-burslari', 'Türkiye Bursları', 'scholarship', '{bachelor,master,phd}'::text[], 'turkey', 'free', '{"ru":"Полностью финансируемая стипендия правительства Турции для иностранных студентов: бакалавриат, магистратура, докторантура и исследовательские программы.","kk":"Түркия Үкіметінің шетелдік студенттерге арналған толық қаржыландырылатын стипендиясы: бакалавриат, магистратура, докторантура және зерттеу бағдарламалары.","en":"A fully funded Turkish government scholarship for international students at bachelor''s, master''s, PhD and research levels."}'::jsonb, '{"ru":"Для иностранных граждан. Условия и сроки уточняйте на официальном сайте.","kk":"Шетел азаматтарына арналған. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"For international citizens. Check conditions and deadlines on the official website."}'::jsonb, 'https://turkiyeburslari.gov.tr', null::date, null::date, 'unverified'),
  ('european-solidarity-corps', 'European Solidarity Corps', 'volunteering', '{any}'::text[], 'europe', 'unknown', '{"ru":"Волонтёрские и общественные проекты в Европе для молодых людей 18–30 лет на портале Европейского союза для молодёжи.","kk":"Еуропалық Одақтың жастар порталындағы 18–30 жас аралығындағы жастарға арналған Еуропадағы еріктілік және қоғамдық жобалар.","en":"Volunteering and community projects in Europe for young people aged 18 to 30 on the European Youth Portal."}'::jsonb, '{"ru":"Участие зависит от проекта и страны проживания. Условия и сроки уточняйте на официальном сайте.","kk":"Қатысу жобаға және тұрғылықты елге байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Participation depends on the project and your country of residence. Check conditions and deadlines on the official website."}'::jsonb, 'https://youth.europa.eu/solidarity_en', null::date, null::date, 'unverified'),
  ('un-volunteers', 'UN Volunteers (UNV)', 'volunteering', '{any}'::text[], 'international', 'unknown', '{"ru":"Программа волонтёров Организации Объединённых Наций. Сайт не открылся при автоматической проверке, поэтому ссылку стоит проверить самому.","kk":"Біріккен Ұлттар Ұйымының еріктілер бағдарламасы. Сайт автоматты тексеру кезінде ашылмады, сондықтан сілтемені өзің тексерген дұрыс.","en":"The United Nations volunteer programme. The site did not open during our automatic check, so please check the link yourself."}'::jsonb, '{"ru":"Условия и сроки уточняйте на официальном сайте.","kk":"Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Check conditions and deadlines on the official website."}'::jsonb, 'https://www.unv.org', null::date, null::date, 'unverified'),
  ('coursera', 'Coursera', 'course', '{any}'::text[], 'online', 'mixed', '{"ru":"Платформа онлайн-курсов от университетов и компаний. На сайте можно посмотреть первый модуль многих курсов бесплатно, а также подать заявку на финансовую помощь.","kk":"Университеттер мен компаниялардың онлайн-курстар платформасы. Сайтта көптеген курстардың бірінші модулін тегін көруге және қаржылық көмекке өтінім беруге болады.","en":"An online learning platform with courses from universities and companies. You can preview the first module of many courses for free and apply for financial aid."}'::jsonb, '{"ru":"Открыто для всех. Что бесплатно, а что нет, зависит от курса. Условия и сроки уточняйте на официальном сайте.","kk":"Барлығына ашық. Не тегін, не ақылы екені курсқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Open to everyone. What is free depends on the course. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.coursera.org', null::date, null::date, 'unverified'),
  ('edx', 'edX', 'course', '{any}'::text[], 'online', 'mixed', '{"ru":"Платформа онлайн-курсов от университетов, в том числе с форматом прослушивания курса (audit).","kk":"Университеттердің онлайн-курстар платформасы, оның ішінде курсты тыңдау (audit) форматы бар.","en":"An online learning platform with university courses, including an audit option for many of them."}'::jsonb, '{"ru":"Открыто для всех. Условия аудита зависят от курса. Условия и сроки уточняйте на официальном сайте.","kk":"Барлығына ашық. Аудит шарттары курсқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Open to everyone. Audit conditions depend on the course. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.edx.org', null::date, null::date, 'unverified'),
  ('cs50x', 'CS50x (Harvard)', 'course', '{any}'::text[], 'online', 'free', '{"ru":"Вводный курс Гарварда по информатике и программированию. Его можно проходить бесплатно, платные только сертификаты и кредиты.","kk":"Гарвардтың информатика және бағдарламалау бойынша кіріспе курсы. Оны тегін өтуге болады, тек сертификаттар мен кредиттер ақылы.","en":"Harvard''s introductory computer science and programming course. It is free to take; only certificates and credit are paid."}'::jsonb, '{"ru":"Предварительные знания не нужны. Условия и сроки уточняйте на официальном сайте.","kk":"Алдын ала білім қажет емес. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"No prior knowledge needed. Check conditions and deadlines on the official website."}'::jsonb, 'https://cs50.harvard.edu/x', null::date, null::date, 'unverified')
